class TidakDitemukanError extends Error {
  constructor(id) {
    super(`Produk ${id} tidak ditemukan`);
    this.name = "TidakDitemukanError";
    this.id = id;
  }
}
const produk = { P01: "Kopi", P02: "Teh" };
function cari(id) {
  if (produk[id] === undefined) throw new TidakDitemukanError(id);
  return produk[id];
}
try {
  console.log(cari("P02"));
  console.log(cari("P09"));
  console.log(cari("P01"));
} catch (e) {
  console.log(e instanceof TidakDitemukanError);
  console.log(e.message);
}

