    super(pesan);
    this.name = "AksesDitolakError";
  }
}
const e = new AksesDitolakError("Khusus admin");
console.log(`${e.name}: ${e.message}`);

class AppError extends Error {}
class LoginError extends AppError {}
try {
  throw new LoginError("Password salah");
} catch (e) {
  console.log(e instanceof AppError, e instanceof Error);
}

